import type {RGB} from '../types'

export type GradientStop = {
  position: number
  color: string
}

export type OpacityGradientStop = {
  position: number
  opacity: number
}

export type GradientCollection = {
  gradient1: GradientStop[]
  gradient2: GradientStop[]
  gradient3: GradientStop[]
}

/**
 * Utility functions for working with color gradients
 */

/**
 * Convert hex color to RGB object
 * @param hex - Hex color string (e.g., '#ff0000')
 * @returns RGB object with r, g, b properties (0-1 range)
 */
export function hexToRgb(hex: string): RGB {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex)
  return result
    ? {
        r: parseInt(result[1]!, 16) / 255,
        g: parseInt(result[2]!, 16) / 255,
        b: parseInt(result[3]!, 16) / 255,
      }
    : {r: 1, g: 1, b: 1}
}

/**
 * Convert RGB object to hex string
 * @param rgb - RGB object with r, g, b properties (0-1 range)
 * @returns Hex color string
 */
export function rgbToHex(rgb: RGB): string {
  const toHex = (c: number): string => {
    const hex = Math.round(c * 255).toString(16)
    return hex.length === 1 ? `0${hex}` : hex
  }
  return `#${toHex(rgb.r)}${toHex(rgb.g)}${toHex(rgb.b)}`
}

/**
 * Interpolate between two colors
 * @param color1 - RGB object
 * @param color2 - RGB object
 * @param t - Interpolation factor (0-1)
 * @returns Interpolated RGB color
 */
export function interpolateColor(color1: RGB, color2: RGB, t: number): RGB {
  return {
    r: color1.r + (color2.r - color1.r) * t,
    g: color1.g + (color2.g - color1.g) * t,
    b: color1.b + (color2.b - color1.b) * t,
  }
}

/**
 * Sample a color from a gradient at a specific position
 * @param gradient - Array of gradient stops {position, color}
 * @param position - Position along gradient (0-1)
 * @returns RGB color object
 */
export function sampleGradient(gradient: GradientStop[], position: number): RGB {
  // Clamp position to 0-1 range
  position = Math.max(0, Math.min(1, position))

  // Sort gradient stops by position (just in case)
  const sortedStops = [...gradient].sort((a, b) => a.position - b.position)

  // Handle edge cases
  if (position <= sortedStops[0]!.position) {
    return hexToRgb(sortedStops[0]!.color)
  }
  if (position >= sortedStops[sortedStops.length - 1]!.position) {
    return hexToRgb(sortedStops[sortedStops.length - 1]!.color)
  }

  // Find the two stops we're between
  let leftStop = sortedStops[0]!
  let rightStop = sortedStops[1]!

  for (let i = 0; i < sortedStops.length - 1; i++) {
    if (position >= sortedStops[i]!.position && position <= sortedStops[i + 1]!.position) {
      leftStop = sortedStops[i]!
      rightStop = sortedStops[i + 1]!
      break
    }
  }

  // Calculate interpolation factor
  const range = rightStop.position - leftStop.position
  const t = range === 0 ? 0 : (position - leftStop.position) / range

  // Interpolate between the two colors
  const leftColor = hexToRgb(leftStop.color)
  const rightColor = hexToRgb(rightStop.color)

  return interpolateColor(leftColor, rightColor, t)
}

/**
 * Get a random gradient from the available gradients
 * @param gradients - Gradients object from settings
 * @returns Random gradient array
 */
export function getRandomGradient(gradients: GradientCollection) {
  const gradientKeys = Object.keys(gradients)
  const randomKey = gradientKeys[Math.floor(Math.random() * gradientKeys.length)]
  return gradients[randomKey as keyof GradientCollection]
}

/**
 * Get a gradient by index from the available gradients
 * @param gradients - Gradients object from settings
 * @param index - Index of the gradient to retrieve
 * @returns Gradient array at the specified index
 */
export function getIndexedGradient(gradients: GradientCollection, index: number): GradientStop[] {
  const gradientKeys = Object.keys(gradients)
  const randomKey = gradientKeys[index % gradientKeys.length]
  return gradients[randomKey as keyof GradientCollection]
}

/**
 * Sample an opacity value from an opacity gradient at a specific position
 * @param opacityGradient - Array of opacity stops {position, opacity}
 * @param position - Position along gradient (0-1)
 * @returns Opacity value (0-1)
 */
export function sampleOpacityGradient(opacityGradient: OpacityGradientStop[], position: number): number {
  // Clamp position to 0-1 range
  position = Math.max(0, Math.min(1, position))

  // Sort opacity stops by position (just in case)
  const sortedStops = [...opacityGradient].sort((a, b) => a.position - b.position)

  // Handle edge cases
  if (position <= sortedStops[0]!.position) {
    return sortedStops[0]!.opacity
  }
  if (position >= sortedStops[sortedStops.length - 1]!.position) {
    return sortedStops[sortedStops.length - 1]!.opacity
  }

  // Find the two stops we're between
  let leftStop = sortedStops[0]!
  let rightStop = sortedStops[1]!

  for (let i = 0; i < sortedStops.length - 1; i++) {
    if (position >= sortedStops[i]!.position && position <= sortedStops[i + 1]!.position) {
      leftStop = sortedStops[i]!
      rightStop = sortedStops[i + 1]!
      break
    }
  }

  // Calculate interpolation factor
  const range = rightStop.position - leftStop.position
  const t = range === 0 ? 0 : (position - leftStop.position) / range

  // Interpolate between the two opacity values
  return leftStop.opacity + (rightStop.opacity - leftStop.opacity) * t
}
