import {CodespacesIcon} from '@primer/octicons-react'
import {ActionList, IconButton} from '@primer/react'
import {memo, useCallback, useMemo} from 'react'

import {strings} from '../../constants'
import {useCodespaceContext} from '../../contexts/CodespaceContext'
import {ReadOnlyKey, useReadOnly} from '../../hooks/use-read-only'
import {useAnalytics} from '../../telemetry/use-analytics'

export const OpenCodespace = memo(function OpenCodespaceButton({
  className,
  variant,
}: {
  className?: string
  variant: 'menu' | 'icon'
}) {
  const readOnly = useReadOnly(ReadOnlyKey.DEFAULT)
  const {codespaceData} = useCodespaceContext()
  const sendEvent = useAnalytics()

  const codespaceName = codespaceData?.codespaceInfo?.environment_data?.friendlyName
  const isReady = codespaceData?.codespaceState === 'ready'
  const isAbleToTargetEdit = isReady && !!codespaceName && !readOnly

  const onCodespaceOpenClick = useCallback(() => {
    if (codespaceName) {
      sendEvent('codespace_open_click', {
        codespace_name: codespaceName,
      })
      window.open(`https://${codespaceName}.github.dev`, '_blank')
    }
  }, [codespaceName, sendEvent])

  const inactiveDescription = useMemo(() => {
    if (!isAbleToTargetEdit) return strings.ACTION_UNAVAILABLE
    return undefined
  }, [isAbleToTargetEdit])

  return variant === 'menu' ? (
    <ActionList.Item
      aria-label="Open codespace"
      onSelect={onCodespaceOpenClick}
      className={className}
      inactiveText={inactiveDescription}
    >
      <ActionList.LeadingVisual>
        <CodespacesIcon />
      </ActionList.LeadingVisual>
      Open codespace
    </ActionList.Item>
  ) : (
    <IconButton
      aria-label="Open codespace"
      className={className}
      icon={CodespacesIcon}
      onClick={() => {
        if (!isAbleToTargetEdit) return
        onCodespaceOpenClick()
      }}
      inactive={!isAbleToTargetEdit}
      description={inactiveDescription}
    />
  )
})
