export const log: typeof console.log = (...args) => {
  if (process.env.NODE_ENV !== 'test') {
    // eslint-disable-next-line no-console
    console.log(...args)
  }
}

export const error: typeof console.error = (...args) => {
  if (process.env.NODE_ENV !== 'test') {
    // eslint-disable-next-line no-console
    console.error(...args)
  }
}

export default {
  log,
  error,
}
