import {isFeatureEnabled} from '@github-ui/feature-flags'
import {lazyWithPreload} from '@github-ui/react-core/lazy-with-preload'
// eslint-disable-next-line no-restricted-imports
import {ScreenSize, useScreenSize} from '@github-ui/screen-size'
import {Banner} from '@github-ui/workspace-editor/components/Banner'
import {
  BrowserIcon,
  BugIcon,
  CodeIcon,
  CommentIcon,
  GearIcon,
  KebabHorizontalIcon,
  MarkGithubIcon,
  SidebarCollapseIcon,
  SidebarExpandIcon,
  XIcon,
} from '@primer/octicons-react'
import {ActionList, ActionMenu, IconButton, Label, Link, SegmentedControl, Stack, useOnEscapePress} from '@primer/react'
import type {DialogHeaderProps} from '@primer/react/experimental'
import {Dialog} from '@primer/react/experimental'
import {clsx} from 'clsx'
import React, {Suspense, useCallback, useEffect, useRef, useState} from 'react'

import {useTargetedEditsContext} from '../../contexts/TargetedEditsContext'
import {useWorkbenchContext} from '../../contexts/WorkbenchContext'
import {useWorkbenchUI} from '../../contexts/WorkbenchUIContext'
import {useFeedbackDialog} from '../../hooks/use-feedback-dialog'
import {useSparkIframeFocus} from '../../hooks/use-spark-iframe-focus'
import type {WorkingMode} from '../../types/workbench-types'
import {focusSidePanelToggleButton, registerSidePanelToggleFocus} from '../../utilities/side-panel-focus-manager'
import {SplitViewIcon} from '../CustomIcons'
import {PublishDropdown} from '../Deployment/PublishDropdown'
import {SparkSwitcher} from '../SparkSwitcher'
import {CreateRepository} from './CreateRepository'
import styles from './Header.module.css'
import {OpenCodespace} from './OpenCodespace'
import {RefreshPreview} from './RefreshPreview'
import {SelectTargetEdit} from './SelectTargetEdit'
import {ToggleMobileView} from './ToggleMobileView'

export interface HeaderProps {
  headerRef: React.RefObject<HTMLDivElement | null>
}

const DebugDialog = React.lazy(() => import('../Debug/DebugDialog'))
const SettingsPanel = lazyWithPreload(async () => ({default: (await import('../SettingsPanel')).SettingsPanel}))

export const WORKING_MODE_ARIA_LABEL = 'Working mode'

const SettingsDialogHeader: React.FC<DialogHeaderProps> = ({
  dialogLabelId,
  dialogDescriptionId,
  title,
  subtitle,
  onClose,
}) => {
  const handleCloseButtonKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLButtonElement>) => {
      // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic -- Needed to ensure Escape closes the dialog even when Primer's close-button tooltip is visible.
      if (event.key !== 'Escape') {
        return
      }

      event.preventDefault()
      event.stopPropagation()
      onClose('close-button')
    },
    [onClose],
  )

  return (
    <Dialog.Header>
      <Stack direction="horizontal" align="center" justify="space-between" gap="condensed">
        <div>
          <Dialog.Title id={dialogLabelId}>{title ?? 'Settings'}</Dialog.Title>
          {subtitle ? <Dialog.Subtitle id={dialogDescriptionId}>{subtitle}</Dialog.Subtitle> : null}
        </div>
        <IconButton
          icon={XIcon}
          aria-label="Close settings"
          variant="invisible"
          onClick={() => onClose('close-button')}
          onKeyDown={handleCloseButtonKeyDown}
        />
      </Stack>
    </Dialog.Header>
  )
}

export const Header = ({headerRef}: HeaderProps) => {
  const [isSettingsOpen, setIsSettingsOpen] = useState(false)
  const [isActionsMenuOpen, setIsActionsMenuOpen] = useState(false)
  const [isDebugDialogOpen, setIsDebugDialogOpen] = useState(false)

  const sidePanelToggleButtonRef = useRef<HTMLButtonElement>(null)
  const settingsButtonRef = useRef<HTMLButtonElement>(null)
  const actionsMenuListRef = useRef<HTMLDivElement>(null)
  const actionsMenuFocusIndexRef = useRef(-1)
  const suppressIframeCloseRef = useRef(false)
  const iframeCloseSuppressionTimeoutRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)

  // This is used to prevent the iframe from closing menus when they are intentionally opened, this was stealing focus towards the iframe and closing the menu.
  const enableIframeCloseSuppression = useCallback((_context: string) => {
    suppressIframeCloseRef.current = true
  }, [])

  const scheduleIframeCloseSuppressionRelease = useCallback((_context: string, delay = 250) => {
    if (iframeCloseSuppressionTimeoutRef.current) {
      clearTimeout(iframeCloseSuppressionTimeoutRef.current)
    }

    iframeCloseSuppressionTimeoutRef.current = setTimeout(() => {
      suppressIframeCloseRef.current = false
      iframeCloseSuppressionTimeoutRef.current = undefined
    }, delay)
  }, [])

  const disableIframeCloseSuppression = useCallback((_context: string) => {
    if (iframeCloseSuppressionTimeoutRef.current) {
      clearTimeout(iframeCloseSuppressionTimeoutRef.current)
      iframeCloseSuppressionTimeoutRef.current = undefined
    }

    if (!suppressIframeCloseRef.current) {
      return
    }

    suppressIframeCloseRef.current = false
  }, [])

  const focusMoreActionsButton = useCallback(() => {
    const trigger = settingsButtonRef.current
    if (!trigger) {
      return
    }

    setTimeout(() => {
      trigger.focus()
    }, 0)
  }, [])

  const onSettingsClose = useCallback(() => {
    setIsSettingsOpen(previous => {
      if (previous) {
        focusMoreActionsButton()
      }
      return false
    })
  }, [focusMoreActionsButton])
  const {targetedEditsEnabled, disableTargetedEdits} = useTargetedEditsContext()
  const {isMobileSidebarOpen, setIsMobileSidebarOpen, id: workbenchId} = useWorkbenchContext()
  const {openFeedback, FeedbackDialog} = useFeedbackDialog(workbenchId)

  const {setWorkingMode, sidePanelOpen, toggleSidePanel, workingMode} = useWorkbenchUI()
  const {screenSize} = useScreenSize()

  useEffect(() => {
    registerSidePanelToggleFocus(() => {
      sidePanelToggleButtonRef.current?.focus()
    })

    return () => {
      registerSidePanelToggleFocus(undefined)
    }
  }, [])

  const handleWorkingModeChange = useCallback(
    (newModeIndex: number) => {
      const newMode = ['preview', 'code', 'split'][newModeIndex] as WorkingMode
      setWorkingMode(newMode)
    },
    [setWorkingMode],
  )

  // Using `hidden` attribute instead of CSS `hide-` class to ensure the button is not focusable
  // and does not interfere with keyboard accessibility.
  const isSmallScreen = screenSize < ScreenSize.medium
  const usesMobileSidePanel = screenSize < ScreenSize.large
  const isLargeScreen = screenSize >= ScreenSize.large
  const isPanelControlActive = usesMobileSidePanel ? isMobileSidebarOpen : sidePanelOpen

  const toggleSidePanelForViewport = useCallback(() => {
    if (usesMobileSidePanel) {
      const nextOpen = !isMobileSidebarOpen
      setIsMobileSidebarOpen(nextOpen)
      toggleSidePanel(nextOpen)
      return
    }

    toggleSidePanel()
  }, [isMobileSidebarOpen, setIsMobileSidebarOpen, toggleSidePanel, usesMobileSidePanel])

  const handleSidePanelButtonClick = useCallback(
    (event: React.MouseEvent<HTMLButtonElement>) => {
      const triggeredViaKeyboard = event.detail === 0
      const isClosing = isPanelControlActive

      toggleSidePanelForViewport()

      if (triggeredViaKeyboard && isClosing) {
        focusSidePanelToggleButton()
      }
    },
    [isPanelControlActive, toggleSidePanelForViewport],
  )

  const setActionsMenuOpen = useCallback(
    (nextOpen: boolean, options?: {force?: boolean}) => {
      if (!nextOpen && !options?.force && suppressIframeCloseRef.current) {
        return
      }

      setIsActionsMenuOpen(nextOpen)

      if (nextOpen) {
        enableIframeCloseSuppression('actions-menu-open')
        scheduleIframeCloseSuppressionRelease('actions-menu-open', 500)
        return
      }

      actionsMenuFocusIndexRef.current = -1
      disableIframeCloseSuppression('actions-menu-open')
    },
    [disableIframeCloseSuppression, enableIframeCloseSuppression, scheduleIframeCloseSuppressionRelease],
  )

  const handleActionMenuOpenChange = useCallback(
    (nextOpen: boolean) => {
      setActionsMenuOpen(nextOpen)
    },
    [setActionsMenuOpen],
  )

  const primeActionsMenuOpen = useCallback(() => {
    if (isActionsMenuOpen) {
      return
    }

    enableIframeCloseSuppression('actions-menu-trigger')
    scheduleIframeCloseSuppressionRelease('actions-menu-trigger', 600)
  }, [enableIframeCloseSuppression, isActionsMenuOpen, scheduleIframeCloseSuppressionRelease])

  useSparkIframeFocus(() => {
    if (suppressIframeCloseRef.current) {
      return
    }

    if (isActionsMenuOpen) {
      setActionsMenuOpen(false, {force: true})
    }
  })

  const handleSettingsEscape = useCallback(
    (event: KeyboardEvent) => {
      if (!isSettingsOpen) {
        return
      }

      event.preventDefault()
      onSettingsClose()
    },
    [isSettingsOpen, onSettingsClose],
  )

  const handleActionsMenuKeyDownCapture = useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic -- Required to override Primer ActionMenu closing behavior so Tab navigates within the open menu.
      if (event.key !== 'Tab') {
        return
      }

      enableIframeCloseSuppression('actions-menu-tab-navigation')
      event.preventDefault()
      event.stopPropagation()
      event.nativeEvent.stopImmediatePropagation?.()

      const container = actionsMenuListRef.current
      if (!container) {
        disableIframeCloseSuppression('actions-menu-tab-navigation:no-container')
        return
      }

      const focusableElements = Array.from(
        container.querySelectorAll<HTMLElement>('button:not([disabled]), [href], [role="menuitem"]'),
        // Primer ActionList uses roving tabindex, so rely on semantic role instead of tabindex filtering.
      ).filter(element => element.offsetParent !== null && element.getAttribute('aria-hidden') !== 'true')

      if (focusableElements.length === 0) {
        disableIframeCloseSuppression('actions-menu-tab-navigation:no-focusable-elements')
        return
      }

      const activeElement = document.activeElement as HTMLElement | null
      let currentIndex = activeElement ? focusableElements.indexOf(activeElement) : -1
      if (currentIndex === -1) {
        currentIndex = actionsMenuFocusIndexRef.current
      }

      const nextIndex =
        currentIndex === -1
          ? event.shiftKey
            ? focusableElements.length - 1
            : 0
          : (currentIndex + (event.shiftKey ? -1 : 1) + focusableElements.length) % focusableElements.length

      actionsMenuFocusIndexRef.current = nextIndex
      focusableElements[nextIndex]?.focus()
      scheduleIframeCloseSuppressionRelease('actions-menu-tab-navigation', 300)
    },
    [disableIframeCloseSuppression, enableIframeCloseSuppression, scheduleIframeCloseSuppressionRelease],
  )

  useEffect(() => {
    return () => {
      if (iframeCloseSuppressionTimeoutRef.current) {
        clearTimeout(iframeCloseSuppressionTimeoutRef.current)
      }
    }
  }, [])

  useOnEscapePress(handleSettingsEscape, [handleSettingsEscape])

  // if we switch to code mode while targeted edits are enabled, we should disable targeted edits
  // to avoid confusion since the code view does not support it
  useEffect(() => {
    if (workingMode === 'code' && targetedEditsEnabled) {
      disableTargetedEdits()
    }
  }, [workingMode, targetedEditsEnabled, disableTargetedEdits])

  return (
    <>
      <div ref={headerRef}>
        <Banner />
        <div className={styles.header}>
          <div className={styles.leftSection}>
            <Stack
              direction="horizontal"
              gap="condensed"
              align="center"
              wrap="nowrap"
              className={clsx(styles.leftSectionContainer, {[styles.sidePanelOpen]: sidePanelOpen})}
            >
              <div className="d-flex flex-items-center">
                {/* GitHub logo */}
                <Link aria-label="Home" href="/">
                  <MarkGithubIcon size={28} verticalAlign="middle" className="color-fg-default" />
                </Link>
                {/* Spark switcher */}
                <div className="mx-1">
                  <SparkSwitcher />
                </div>
              </div>
              {/* Side Panel expander */}
              <div className={styles.sidePanelExpander}>
                <IconButton
                  icon={isPanelControlActive ? SidebarCollapseIcon : SidebarExpandIcon}
                  aria-label={isPanelControlActive ? 'Collapse side panel' : 'Expand side panel'}
                  aria-pressed={isPanelControlActive}
                  onClick={handleSidePanelButtonClick}
                  ref={sidePanelToggleButtonRef}
                  data-workbench-side-panel-toggle
                  className={styles.expandSidebarButton}
                />
              </div>
            </Stack>
          </div>

          <div className={styles.centerSection}>
            {/* Working mode selector */}
            <SegmentedControl
              aria-label={WORKING_MODE_ARIA_LABEL}
              onChange={handleWorkingModeChange}
              className="hide-sm fgColor-muted"
            >
              <SegmentedControl.IconButton
                selected={workingMode === 'preview'}
                icon={BrowserIcon}
                aria-label="Preview mode"
              />
              <SegmentedControl.IconButton
                selected={workingMode === 'code'}
                icon={CodeIcon}
                aria-label="Code mode"
                className={styles.codeButton}
              />
              <SegmentedControl.IconButton
                selected={workingMode === 'split'}
                icon={<SplitViewIcon className="octicon" />}
                aria-label="Why not both?"
                className="hide-sm hide-md hide-lg"
              />
            </SegmentedControl>
          </div>

          <Stack direction="horizontal" gap="condensed" align="center" justify="end" className={styles.rightSection}>
            <SelectTargetEdit variant="icon" />
            <RefreshPreview variant="icon" />
            <ToggleMobileView variant="icon" />
            <ActionMenu
              anchorRef={settingsButtonRef}
              open={isActionsMenuOpen}
              onOpenChange={handleActionMenuOpenChange}
            >
              <ActionMenu.Anchor ref={settingsButtonRef}>
                <IconButton
                  icon={KebabHorizontalIcon}
                  aria-label="More actions"
                  onMouseDown={primeActionsMenuOpen}
                  onKeyDown={event => {
                    // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic -- Need to preemptively suppress iframe blur before Primer processes Enter/Space to open the menu.
                    if (event.key === 'Enter' || event.key === ' ') {
                      primeActionsMenuOpen()
                    }
                  }}
                />
              </ActionMenu.Anchor>
              <ActionMenu.Overlay width="small">
                <div ref={actionsMenuListRef} onKeyDownCapture={handleActionsMenuKeyDownCapture}>
                  <ActionList>
                    {isSmallScreen ? (
                      <>
                        <ActionList.Group selectionVariant="single">
                          <ActionList.Item
                            aria-label="Preview mode"
                            selected={workingMode === 'preview'}
                            onSelect={() => setWorkingMode('preview')}
                          >
                            <ActionList.LeadingVisual>
                              <BrowserIcon />
                            </ActionList.LeadingVisual>
                            Preview mode
                          </ActionList.Item>
                          <ActionList.Item
                            aria-label="Code mode"
                            selected={workingMode === 'code'}
                            onSelect={() => setWorkingMode('code')}
                          >
                            <ActionList.LeadingVisual>
                              <CodeIcon />
                            </ActionList.LeadingVisual>
                            Code mode
                          </ActionList.Item>
                        </ActionList.Group>
                        <ActionList.Divider className="hide-md hide-lg hide-xl" />
                      </>
                    ) : null}
                    <SelectTargetEdit variant="menu" />
                    <RefreshPreview variant="menu" />
                    <ToggleMobileView variant="menu" />
                    <ActionMenu.Divider className="hide-lg hide-xl" />
                    <OpenCodespace variant="menu" />
                    <CreateRepository />
                    <ActionList.Item
                      aria-label="Settings"
                      onSelect={() => setIsSettingsOpen(!isSettingsOpen)}
                      onMouseEnter={() => SettingsPanel.preload()}
                      onFocus={() => SettingsPanel.preload()}
                    >
                      <ActionList.LeadingVisual>
                        <GearIcon />
                      </ActionList.LeadingVisual>
                      Settings
                    </ActionList.Item>
                    <>
                      <ActionList.Divider />
                      {isFeatureEnabled('copilot_workbench_debug_panel') && (
                        <ActionList.Item
                          aria-label="Debug panel"
                          onSelect={() => {
                            setIsDebugDialogOpen(true)
                          }}
                        >
                          <ActionList.LeadingVisual>
                            <BugIcon />
                          </ActionList.LeadingVisual>
                          Debug panel
                          <ActionList.TrailingVisual>
                            <Label variant="attention">Staff</Label>
                          </ActionList.TrailingVisual>
                        </ActionList.Item>
                      )}
                      <ActionList.Item aria-label="Send feedback" onSelect={() => openFeedback()}>
                        <ActionList.LeadingVisual>
                          <CommentIcon />
                        </ActionList.LeadingVisual>
                        Send feedback
                      </ActionList.Item>
                    </>
                    <PublishDropdown variant="menu" hidden={isLargeScreen} />
                  </ActionList>
                </div>
              </ActionMenu.Overlay>
            </ActionMenu>
            {isSettingsOpen && (
              <Dialog
                title="Settings"
                onClose={onSettingsClose}
                position="right"
                returnFocusRef={settingsButtonRef}
                renderHeader={SettingsDialogHeader}
              >
                <Suspense>
                  <SettingsPanel />
                </Suspense>
              </Dialog>
            )}
            {isDebugDialogOpen && (
              // We lazy-load the DebugDialog to avoid loading it unnecessarily. We don't need a fallback.
              <Suspense fallback={null}>
                <DebugDialog onClose={() => setIsDebugDialogOpen(false)} />
              </Suspense>
            )}
            <FeedbackDialog returnFocusRef={settingsButtonRef} />
            <PublishDropdown className="hide-sm hide-md" />
          </Stack>
        </div>
      </div>
    </>
  )
}
