import {isFeatureEnabled} from '@github-ui/feature-flags'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {verifiedFetch} from '@github-ui/verified-fetch'
import type React from 'react'
import {createContext, use, useCallback, useEffect, useMemo, useRef, useState} from 'react'

import {useAnalytics} from '../telemetry/use-analytics'
import {type DeploymentVisibility, DeploymentVisibilitySetting} from '../types/deployment-types'
import type {Iteration, UserOrganization, WorkbenchRoutePayload} from '../types/workbench-types'
import {CommandTask} from '../utilities/terminal-reducer'
import {workbenchDeployUrl} from '../utilities/urls'
import {useCodespaceContext} from './CodespaceContext'
import {UNCOMMITTED_HASH, useIterationHistory} from './IterationHistoryContext'
import {useSparkServerStatus} from './ServerEventsContext'
import {useTerminalContext} from './TerminalContext'
import {useWorkbenchContext} from './WorkbenchContext'
import {AgentStatus, Service, useAgentStatus, useWorkbenchStore} from './WorkbenchStoreContext'

export interface PublishingContextProps {}

export type PublishingStatus =
  | 'unpublished'
  | 'publishingFirstTime'
  | 'published'
  | 'republishing'
  | 'republishFailed'
  | 'republishCanceled'

export const getLatestPublishedIterationSha = (iterations: Iteration[]): string | undefined => {
  for (let i = iterations.length - 1; i >= 0; i -= 1) {
    const sha = iterations[i]?.sha
    if (sha && sha !== UNCOMMITTED_HASH) {
      return sha
    }
  }
  return undefined
}

export interface PublishingContextData {
  publishingStatus: PublishingStatus // The state machine status. See external docs for reference.
  publishedUrl?: string // The URL for the published deployment
  isPublishUpToDate: boolean // Is the published spark on the same SHA as our most recent iteration?
  previewUrl: string // The URL for the read-only preview
  canCurrentlyPublish: boolean // Is now a time that the publishing action can happen?
  visibility: DeploymentVisibilitySetting // The visibility of published sparks (private? all github?, etc)
  visibilityOrganizationId: number | null // The organization ID for selected_orgs visibility
  readOnlyKv: boolean // If KV is readonly for app users (not owner)
  updateVisibility: (newVisibility: DeploymentVisibility) => Promise<boolean> // Set the visibility of the deployment
  updateDataAccess: (isReadonly: boolean) => Promise<boolean> // Set the data access of the deployment
  startDeploymentPipeline: () => Promise<void> // Start the publishing process
  unpublish: () => Promise<void> // Unpublish the deployment
  cancelPublishing: () => void // Cancel an active publishing process
  deployedAt: string | undefined
  deploymentSha: string | undefined
  organizationsPublishableTo: UserOrganization[] // Organizations the user can publish to
  canPublishToAllGithub: boolean // Whether the user can publish to all of GitHub
}

export const PublishingContext = createContext<PublishingContextData | undefined>(undefined)

export const PublishingProvider: React.FC<PublishingContextProps & {children: React.ReactNode}> = ({children}) => {
  const {
    codespaceData: {codespaceState},
  } = useCodespaceContext()
  const {
    executeCommand,
    stopCommand,
    state: {history},
  } = useTerminalContext()
  const deployCommand = history[CommandTask.Deploy]
  const {friendlyName} = useWorkbenchContext()
  const {isAgentBusy} = useAgentStatus()

  const {
    status: {[Service.AGENT]: agentStatus},
  } = useWorkbenchStore()
  const {workbench, organizations, canDeployToAllGithub = true} = useRoutePayload<WorkbenchRoutePayload>()
  const {isServerConnected} = useSparkServerStatus()

  const {deploy, refetch: refetchWorkbench} = useWorkbenchContext()

  const {previousRefinements} = useIterationHistory()
  const latestIterationSha = useMemo(() => getLatestPublishedIterationSha(previousRefinements), [previousRefinements])

  const [publishingStatus, setPublishingStatus] = useState<PublishingStatus>('unpublished')
  const [publishedUrl, setPublishedUrl] = useState<string | undefined>(undefined)
  const [publishStartTime, setPublishStartTime] = useState<number | undefined>(undefined)
  const [publishVisibility, setPublishVisibility] = useState<DeploymentVisibility>({
    setting: workbench?.runtime?.app?.deploymentVisibility?.setting || DeploymentVisibilitySetting.OnlyOwner,
    organizationId: workbench?.runtime?.app?.deploymentVisibility?.organizationId || null,
  })
  const [readOnlyKv, setReadOnlyKv] = useState<boolean>(workbench?.runtime?.app?.readOnlyKv ?? false)

  // using ref because this is internal flag that doesn't need to trigger re-render
  const republishCanceledRef = useRef(false)

  const deployUrl = deploy
    ? workbenchDeployUrl({friendlyName, deployLogin: deploy.deployLogin, domainBase: deploy.domainBase})
    : ''
  const previewUrl = deploy
    ? `https://${deploy.displayName}--${friendlyName}--${deploy.deployLogin}.${deploy.domainBase}`
    : ''
  const statusFromPayload = deploy ? 'success' : 'failure'

  useEffect(() => {
    // Determine if the payload contains the deploy object,
    // which would indicate that there was a previous deployment.
    // If so, set the publishing status to published.
    if (deploy) {
      setPublishingStatus('published')
      setPublishedUrl(deployUrl)
    }
  }, [deploy, deployUrl, friendlyName])

  const urlForTelemetry = useCallback(() => {
    return deploy
      ? deployUrl
      : workbenchDeployUrl({
          friendlyName,
          deployLogin: workbench.runtime.owner.deployLogin,
          domainBase: workbench.runtime.owner.deploymentDomainBase,
        })
  }, [deploy, friendlyName, deployUrl, workbench])

  const sendEvent = useAnalytics()

  const startDeploymentPipeline = useCallback(async () => {
    const startTime = Date.now()
    try {
      const newStatus = publishingStatus === 'unpublished' ? 'publishingFirstTime' : 'republishing'
      setPublishingStatus(newStatus)
      setPublishStartTime(startTime)
      sendEvent('spark_deployed', {
        publishing_status: newStatus,
        url: urlForTelemetry(),
        visibility: publishVisibility.setting,
        visibility_organization_id: publishVisibility.organizationId,
      })

      const deployScript =
        process.env.NODE_ENV === 'development'
          ? `GITHUB_RUNTIME_PERMANENT_NAME=${workbench.runtime.app.permanentName} /workspaces/workbench-sdk/spark-agent/src/uploads/local-deploy.sh`
          : `/usr/local/bin/deploy.sh`
      const command = `${deployScript} | tee -a /var/log/spark-publishing.log`
      await executeCommand(command, CommandTask.Deploy)
      refetchWorkbench()
    } catch {
      const errorStatus =
        publishingStatus === 'publishingFirstTime'
          ? 'unpublished'
          : republishCanceledRef.current
            ? 'republishCanceled'
            : 'republishFailed'

      setPublishingStatus(errorStatus)
      sendEvent('deploy_status', {
        duration_ms: Date.now() - startTime,
        publishing_status: errorStatus,
        success: false,
        url: urlForTelemetry(),
        visibility: publishVisibility.setting,
        visibility_organization_id: publishVisibility.organizationId,
      })

      // cleanup flag
      republishCanceledRef.current = false
    }
  }, [publishingStatus, sendEvent, urlForTelemetry, publishVisibility, workbench, executeCommand, refetchWorkbench])

  const unpublish = useCallback(async () => {
    // NO-OP right now
    // TODO:
    // 1. Create the unpublish API in dotcom
    // 2. use verifiedFetch to call the API
    // 3. Update the publishingStatus to unpublished
    // 4. Update the publishedUrl to undefined
  }, [])

  const cancelPublishing = useCallback(() => {
    republishCanceledRef.current = true
    stopCommand(deployCommand)
  }, [stopCommand, deployCommand])

  const {output, loading, startTime, endTime, stopped: isCommandStopped} = deployCommand

  const updateVisibility = useCallback(
    async (newVisibility: DeploymentVisibility): Promise<boolean> => {
      // Optimisticially update the visibility in the UI
      setPublishVisibility(newVisibility)

      const requestBody = {
        visibility: newVisibility.setting,
        visibility_organization_id: newVisibility.organizationId,
      }

      // Send update...
      const shareStartTime = Date.now()

      const response = await verifiedFetch(`/copilot/spark/runtime/deployment/${workbench.id}`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(requestBody),
      })

      if (response.ok) {
        sendEvent('spark_shared', {
          duration_ms: Date.now() - shareStartTime,
          visibility: newVisibility.setting,
          visibility_organization_id: newVisibility.organizationId,
          success: true,
        })
        return true
      } else {
        // Revert visibility selection if didn't apply
        setPublishVisibility(publishVisibility)
        sendEvent('spark_shared', {
          duration_ms: Date.now() - shareStartTime,
          visibility: newVisibility.setting,
          visibility_organization_id: newVisibility.organizationId,
          success: false,
        })
        return false
      }
    },
    [workbench.id, sendEvent, publishVisibility],
  )

  const updateDataAccess = useCallback(
    async (isReadonly: boolean): Promise<boolean> => {
      // Optimistically update the visibility in the UI
      setReadOnlyKv(isReadonly)

      const requestBody = {
        read_only_kv: isReadonly,
      }

      // Send update...
      const dataAccessStartTime = Date.now()

      try {
        await verifiedFetch(`/copilot/spark/runtime/deployment/${workbench.id}`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(requestBody),
        })

        sendEvent('data_access_updated', {
          duration_ms: Date.now() - dataAccessStartTime,
          is_readonly: isReadonly,
          success: true,
        })
        return true
      } catch (error) {
        setReadOnlyKv(readOnlyKv)
        sendEvent('data_access_updated', {
          duration_ms: Date.now() - dataAccessStartTime,
          is_readonly: isReadonly,
          success: false,
          error: error instanceof Error ? error.message : String(error),
        })
        return false
      }
    },
    [workbench.id, sendEvent, readOnlyKv],
  )

  // Only try to parse the command output and status if we're in the process of publishing.
  useEffect(() => {
    if (publishingStatus === 'publishingFirstTime' || publishingStatus === 'republishing') {
      // The best way we've determined if the command is still running is to check if the start time is set and the end time is not.
      const isCommandExecuting = !!(startTime && !endTime) || loading

      const isBuildComplete = output.includes(`[--Build: Complete--]`)
      const isDeployComplete = output.includes(`[--Deployment: Complete--]`)

      const urlMatches = output.match(/https:\/\/.*\.github\.app/)
      const urlFromCommands = !isCommandExecuting && urlMatches ? urlMatches[0] : ''

      const buildStatusFromCommands =
        !isCommandExecuting && !isBuildComplete ? 'failure' : isBuildComplete ? 'success' : 'pending'
      const deployStatusFromCommands = isCommandExecuting ? 'pending' : isDeployComplete ? 'success' : 'failure'

      const publishingUrl = deployUrl || urlFromCommands

      const buildStatus = startTime ? buildStatusFromCommands : statusFromPayload
      const deployStatus = startTime ? deployStatusFromCommands : statusFromPayload

      // Once the command has finished, we'll try to understand what to transition the state to.
      if (!isCommandExecuting || isCommandStopped) {
        setPublishStartTime(undefined)
        if (deployStatus === 'success' && buildStatus === 'success') {
          setPublishingStatus('published')
          setPublishedUrl(publishingUrl)
          sendEvent('deploy_status', {
            duration_ms: publishStartTime ? Date.now() - publishStartTime : 0,
            publishing_status: status,
            success: true,
            url: publishingUrl,
            visibility: publishVisibility.setting,
            visibility_organization_id: publishVisibility.organizationId,
          })
        } else {
          const status =
            publishingStatus === 'republishing'
              ? republishCanceledRef.current
                ? 'republishCanceled'
                : 'republishFailed'
              : 'unpublished'
          setPublishingStatus(status)
          sendEvent('deploy_status', {
            duration_ms: publishStartTime ? Date.now() - publishStartTime : 0,
            publishing_status: status,
            success: false,
            url: publishingUrl,
            visibility: publishVisibility.setting,
            visibility_organization_id: publishVisibility.organizationId,
          })

          republishCanceledRef.current = false
        }
      }
    }
  }, [
    publishingStatus,
    startTime,
    endTime,
    loading,
    output,
    statusFromPayload,
    isCommandStopped,
    sendEvent,
    publishStartTime,
    publishVisibility,
    deployUrl,
  ])

  const canCurrentlyPublish =
    !loading &&
    !isAgentBusy &&
    (isFeatureEnabled('spark_server_connection_status')
      ? isServerConnected
      : codespaceState === 'ready' && agentStatus === AgentStatus.CONNECTED)

  const deployedAt = deploy?.createdAt
  const deploymentSha = deploy?.revision
  const isPublishUpToDate = latestIterationSha === deploymentSha
  const contextValue = useMemo(
    () => ({
      publishingStatus,
      publishedUrl,
      canCurrentlyPublish,
      startDeploymentPipeline,
      visibility: publishVisibility.setting,
      visibilityOrganizationId: publishVisibility.organizationId,
      readOnlyKv,
      updateVisibility,
      updateDataAccess,
      unpublish,
      cancelPublishing,
      previewUrl,
      isPublishUpToDate,
      deployedAt,
      deploymentSha,
      organizationsPublishableTo: organizations,
      canPublishToAllGithub: canDeployToAllGithub,
    }),
    [
      publishingStatus,
      publishedUrl,
      canCurrentlyPublish,
      startDeploymentPipeline,
      publishVisibility,
      readOnlyKv,
      updateVisibility,
      updateDataAccess,
      unpublish,
      cancelPublishing,
      previewUrl,
      isPublishUpToDate,
      deployedAt,
      deploymentSha,
      organizations,
      canDeployToAllGithub,
    ],
  )

  return <PublishingContext value={contextValue}>{children}</PublishingContext>
}

export const usePublishingContext = () => {
  const context = use(PublishingContext)
  if (!context) {
    throw new Error('usePublishing must be used within a PublishingProvider')
  }
  return context
}
