import {AlertIcon} from '@primer/octicons-react'
import {LinkButton} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'

import styles from './UnsupportedFile.module.css'

export default function UnsupportedFile({path, value}: {path: string; value?: string}) {
  return (
    <div className={styles.unsupportedFileContainer}>
      <Blankslate>
        <Blankslate.Visual>
          <AlertIcon size="medium" />
        </Blankslate.Visual>
        <Blankslate.Heading>Unsupported file type</Blankslate.Heading>
        <Blankslate.Description>
          {"We aren't able to preview this file in the editor. You can download it to view it locally."}
        </Blankslate.Description>
        {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
        <LinkButton as="a" href={value} download={path.split('/').pop()} variant="primary" className="tmp-mt-3">
          Download File
        </LinkButton>
      </Blankslate>
    </div>
  )
}
