import {lazyWithPreload} from '@github-ui/react-core/lazy-with-preload'
import {AiModelIcon, DatabaseIcon, ImageIcon, PaintbrushIcon, SparkleFillIcon} from '@primer/octicons-react'
import {clsx} from 'clsx'
import {Suspense, useEffect, useRef} from 'react'

import {useTargetedEditsContext} from '../../contexts/TargetedEditsContext'
import {useWorkbenchUI} from '../../contexts/WorkbenchUIContext'
import type {UseWorkbenchReturn} from '../../hooks/use-workbench'
import {Panel, type Panel as PanelType} from '../../types/workbench-types'
import {TargetIcon} from '../CustomIcons'
import {WORKING_MODE_ARIA_LABEL} from '../Header/Header'
import {TARGETED_EDITS_INPUT_ID} from '../TargetedEditsInput'
import {PanelBlankslate} from './PanelBlankslate'
import IteratePanel from './panels/IteratePanel/IteratePanel'
import styles from './SidePanel.module.css'

const AiPanel = lazyWithPreload(async () => ({default: (await import('./panels/AiPanel')).AiPanel}))
const AssetsPanel = lazyWithPreload(async () => ({default: (await import('./panels/AssetsPanel')).AssetsPanel}))
const ThemePanel = lazyWithPreload(async () => ({default: (await import('./panels/ThemePanel')).ThemePanel}))
const TargetedEditsPanel = lazyWithPreload(async () => ({
  default: (await import('./panels/TargetedEditsPanel')).TargetedEditsPanel,
}))
const DataPanel = lazyWithPreload(async () => ({default: (await import('./panels/DataPanel')).DataPanel}))

const PANELS = [
  {type: Panel.ITERATE, label: 'Iterate', icon: SparkleFillIcon},
  {type: Panel.THEME, label: 'Theme', icon: PaintbrushIcon, preload: ThemePanel.preload},
  {type: Panel.DATA, label: 'Data', icon: DatabaseIcon, preload: DataPanel.preload},
  {type: Panel.AI, label: 'Prompts', icon: AiModelIcon, preload: AiPanel.preload},
  {type: Panel.ASSETS, label: 'Assets', icon: ImageIcon, preload: AssetsPanel.preload},
]

const TAB_ID_PREFIX = 'spark-side-panel-tab-'
const TAB_PANEL_ID = 'spark-side-panel-tabpanel'
const TABLIST_ARIA_LABEL = 'Workbench side panel tabs'

interface SidePanelProps {
  workbenchData: UseWorkbenchReturn
  selectedPanel: PanelType
  setSelectedPanel: (panel: PanelType) => void
  onRequestCollapse?: (reason: 'escape') => void
}

export function SidePanel({workbenchData, selectedPanel, setSelectedPanel, onRequestCollapse}: SidePanelProps) {
  const {sidePanelOpen} = useWorkbenchUI()
  const {selectedElement, targetedEditsEnabled, disableTargetedEdits} = useTargetedEditsContext()

  const containerRef = useRef<HTMLDivElement>(null)
  const selectedTabId = `${TAB_ID_PREFIX}${selectedPanel}`

  // Remove the side panel from pointer and keyboard interaction when it is collapsed.
  useEffect(() => {
    const container = containerRef.current
    if (!container) {
      return
    }

    container.toggleAttribute('inert', !sidePanelOpen)
  }, [sidePanelOpen])

  useEffect(() => {
    if (targetedEditsEnabled) {
      TargetedEditsPanel.preload()
      setSelectedPanel('theme')
    }
  }, [targetedEditsEnabled, setSelectedPanel])

  useEffect(() => {
    if (!sidePanelOpen || !onRequestCollapse) {
      return
    }

    const handleKeyDown = (event: KeyboardEvent) => {
      // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic -- Escape collapses the local side panel when focus is within it.
      if (event.key !== 'Escape') {
        return
      }

      const activeElement = document.activeElement
      if (!activeElement || !containerRef.current?.contains(activeElement)) {
        return
      }

      event.preventDefault()
      event.stopPropagation()
      onRequestCollapse('escape')
    }

    document.addEventListener('keydown', handleKeyDown)
    return () => {
      document.removeEventListener('keydown', handleKeyDown)
    }
  }, [onRequestCollapse, sidePanelOpen])

  /**
   * for the best UX we want to disable targeted edits when the user clicks outside the preview except for specific elements
   * the `setTimeout` is used to ensure that the event listener is added after the component has mounted.
   */
  useEffect(() => {
    if (!targetedEditsEnabled) {
      return
    }

    const handleWindowClick = (event: MouseEvent) => {
      const EXCLUDED_ELEMENTS = [
        containerRef.current,
        document.querySelector(`[aria-label="${WORKING_MODE_ARIA_LABEL}"]`),
        document.getElementById(TARGETED_EDITS_INPUT_ID),
      ]

      if (!EXCLUDED_ELEMENTS.some(element => element?.contains(event.target as Node))) {
        disableTargetedEdits()
      }
    }

    const workbenchRoot = document.getElementById('workbench-root')!

    const timeoutId = setTimeout(() => {
      // Add event listener to handle clicks outside the panel
      workbenchRoot.addEventListener('click', handleWindowClick)
    }, 100)

    // Cleanup the event listener on unmount
    return () => {
      workbenchRoot.removeEventListener('click', handleWindowClick)
      clearTimeout(timeoutId)
    }
  }, [targetedEditsEnabled, disableTargetedEdits])

  return (
    <div className={styles.container} ref={containerRef} aria-hidden={!sidePanelOpen} data-testid="side-panel">
      {/* Horizontal navigation bar */}
      <div className={styles.navContainer}>
        <div className={styles.navList} role="tablist" aria-label={TABLIST_ARIA_LABEL}>
          {PANELS.map(panel => {
            const tabId = `${TAB_ID_PREFIX}${panel.type}`
            return (
              <button
                type="button"
                key={panel.type}
                className={clsx(styles.navButton, {
                  [styles.navButtonActive]: selectedPanel === panel.type,
                })}
                id={tabId}
                role="tab"
                aria-selected={selectedPanel === panel.type}
                aria-controls={TAB_PANEL_ID}
                onClick={() => {
                  setSelectedPanel(panel.type)
                  // Reset targeted edits when switching to theme panel
                  if (targetedEditsEnabled) {
                    disableTargetedEdits()
                  }
                }}
                onMouseEnter={() => panel.preload?.()}
                onFocus={() => panel.preload?.()}
              >
                <span className={styles.navButtonLabel}>{panel.label}</span>
                {/* This is a visually hidden copy of the label that is always bold to prevent layout shift when tab selection changes */}
                <span className={styles.navButtonLabelInvisible} aria-hidden="true">
                  {panel.label}
                </span>
              </button>
            )
          })}
        </div>
      </div>

      {/* Panel content area */}
      <div className={styles.panel} role="tabpanel" id={TAB_PANEL_ID} aria-labelledby={selectedTabId}>
        {selectedPanel === 'iterate' && <IteratePanel workbenchData={workbenchData} />}
        {selectedPanel === 'theme' &&
          (targetedEditsEnabled ? (
            selectedElement ? (
              <Suspense>
                <TargetedEditsPanel
                  key={JSON.stringify(selectedElement.location?.start ?? selectedElement.component.location?.start)}
                  element={selectedElement}
                  onClose={() => {
                    disableTargetedEdits()
                    setSelectedPanel('theme')
                  }}
                />
              </Suspense>
            ) : (
              <PanelBlankslate title="Select an element to edit" icon={TargetIcon} />
            )
          ) : (
            <Suspense>
              <ThemePanel />
            </Suspense>
          ))}
        {selectedPanel === 'data' && (
          <Suspense>
            <DataPanel />
          </Suspense>
        )}
        {selectedPanel === 'ai' && (
          <Suspense>
            <AiPanel />
          </Suspense>
        )}
        {selectedPanel === 'assets' && (
          <Suspense>
            <AssetsPanel />
          </Suspense>
        )}
      </div>
    </div>
  )
}
