interface AudioPreviewProps {
  src: string
  className?: string
  onError?: (error: Error) => void
}

export function AudioPreview({src, className, onError}: AudioPreviewProps) {
  const handleError = (_e: React.SyntheticEvent<HTMLAudioElement>) => {
    const error = new Error('Audio loading failed')
    if (onError) {
      onError(error)
    }
  }

  if (!src || (!src.startsWith('blob:') && !src.startsWith('data:audio/'))) {
    return (
      <div className="d-flex flex-column flex-justify-center flex-items-center height-full tmp-p-4">
        <p>Error loading audio file. The file may be corrupted or not a valid audio format.</p>
      </div>
    )
  }

  return (
    <div className="d-flex flex-justify-center flex-items-center height-full tmp-p-4">
      {/* eslint-disable-next-line jsx-a11y/media-has-caption */}
      <audio controls src={src} className={`width-full ${className || ''}`} onError={handleError}>
        Your browser does not support the audio element.
      </audio>
    </div>
  )
}
